    "difficulty": 3,
    "question": "次は、知能の理論に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。\n\n知能の心理学研究においては、主として二つの立場がある。知的情報処理の対象となる事柄の内容の違いを超えて共通する一つの一般的な機能があるとする立場と、そのような機能はないか、あってもその力は弱く、むしろ異なる複数の機能が並立するという立場である。\n\n前者の代表である［A］は、高校生の様々な学業成績の間に［B］の相関が見られることに着目し、［C］を用いた研究によって、様々な知的活動に共通する一般的な精神能力が存在することを実証的に示した。他方、後者の立場をとるL. L. サーストンは、知能はいくつかの基本的要素に分類できると考え、多くの検査を施行し、同じく［C］の手法を用いながら、「言語理解」、「空間」、「知覚速度」など7種類の基本的精神能力の存在を指摘した。\n\n双方の立場を統合する集大成として、近年広く受け入れられているのが、［D］を発展・整理して提唱された［E］である。この理論において、知能は階層的に整理され、「限定的能力」、「広範囲能力」、「一般知能」の三階層から構成される。今日主要な知能検査を作成ないし改訂する際には、この理論が考慮されるようになっている。",
