      "イ": "等価性の確認や独立した翻訳者に関する説明は合っている。丁度可知差異は刺激の差を知覚できる最小差に関わる概念で、ここでは項目反応理論などで検討する特異項目機能が当てはまる。",
      "ウ": "文化の間で尺度が同じ構成概念を測るには測定の等価性が必要で、逆翻訳は異なる人に行ってもらう。同程度の特性でも集団によって項目への反応が異なる特異項目機能は、項目反応理論などで調べられる。",
