    "difficulty": 3,
    "question": "次は、間接効果の推定に関する記述であるが、ア～オに当てはまるものの組合せとして最も妥当なのはどれか。\nただし、解答に際しては、標準正規分布表を参照すること。\n\n間接効果とは、図のように変数Xと変数Yとの間に変数Mを仮定したときに、効果aと効果bの［ア］によって求められる。変数Xと変数Yとの間の効果は総合効果と呼ばれ、図における効果c（直接効果）と間接効果の［イ］に一致する。このときの変数Mは［ウ］と呼ばれる。\n標本サイズが大きいとき、間接効果の標本分布が正規分布に近似する性質を利用し、検定統計量Zを用いる方法をソベル法（デルタ法と呼ばれることもある）という。間接効果が0.05、間接効果の標準誤差が0.03であるとき、間接効果の有意性検定をソベル法によって行うと、検定統計量Zは約［エ］であり、有意水準を5％（両側検定）としたとき、間接効果は統計的に［オ］と判断できる。",
