    "question": "次は、心理学研究における研究倫理に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。\n\n心理学を含む、人を対象とする研究の実施に際しては、人格の尊重、善行、公正という三つの研究倫理の原則を守らなければならない。例えば、研究の実施に際し、研究に関する情報や説明に基づいて研究参加者から同意を得る［A］は、1点目の人格の尊重に関わる問題である。\nまた、心理学研究を含む研究活動においては、特定不正行為と呼ばれる不正行為が知られている。存在しないデータや研究結果等を作成する［B］や、他の研究者のアイディアなどを適切に引用等せずに無断で流用する［C］などが含まれる。このような深刻な不正行為に加え、問題のある研究実践（Questionable Research Practice）と呼ばれる手続についても注意が必要である。例えば、結果が分かった後に仮説を立てる［D］や、研究者が望む有意な検定結果をもたらすデータを得られたことにするよう操作を行う［E］が挙げられる。",
