    "question": "次は、基本統計量（要約統計量）に関する記述であるが、A～Dに当てはまるものの組合せとして最も妥当なのはどれか。\n\n社会調査において、集めたデータの全体的な特徴を客観的な数値で表して把握するに当たり、基本統計量（要約統計量）が用いられる。\n集めたデータの分布の形状が、山が一つで左右対称な釣鐘型をしているとき、これは正規分布と呼ばれる。基本統計量には、正規分布からのずれの程度を示す指標があり、このうち、データが正規分布を基準とした状態からどの程度左右にずれているかを示すものは［A］と呼ばれ、正規分布のときのその値は［B］となる。\nまた、基本統計量のうち、集めたデータの中心傾向を一つの数値で表現したものは代表値と呼ばれ、代表値にはメディアン（median）やモード（mode）などの種類がある。例えば、図は、ある学級で25人の生徒に英語の試験を実施した結果を表したものであるが、これらの生徒におけるこの試験のメディアン（median）は［C］、モード（mode）は［D］である。",
