      "イ": "unconditioned response (UCR) ／ conditioned response (CR) ／ ㋑ ／ ㋓ ／ 100 ／ 0",
      "ウ": "unconditioned response (UCR) ／ conditioned response (CR) ／ ㋑ ／ ㋒ ／ 0 ／ 100",
      "エ": "conditioned response (CR) ／ unconditioned response (UCR) ／ ㋐ ／ ㋒ ／ 100 ／ 0",
