      "ウ": "ベック抑うつ質問票（BDI-Ⅱ）は、周囲の者によって抑うつ症状をアセスメントする他者評定式の質問紙検査で、重症度の評価や治療の経過観察等で用いられることが多い。過去1週間の気分について、「怒り－敵意」、「混乱－当惑」、「抑うつ－落ち込み」、「疲労－無気力」、「緊張－不安」、「活気－活力」の6尺度と、ネガティブな気分状態を総合的に表すT得点から抑うつ症状を測定する。",
