    "question": "次は、動機づけに係る理論に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。\n\nE. L. デシとR. M. ライアンによって構築された［A］とは、内発的動機づけ研究から発展してきた理論体系である。この理論は、人の成長と発達、ウェルビーイングを導く動機づけの在り方を説明する枠組みを特徴とする。現在のところ、認知的評価理論、有機的統合理論、因果志向性理論、基本的心理欲求理論、目標内容理論、関係性動機づけ理論という六つのミニ理論で構成される。興味や関心をもっている活動に対して金銭のような外的な報酬が与えられると、その後の内発的動機づけが低下する現象を［B］というが、この現象が発生する理由については、認知的評価理論の枠組みから解釈されることが多い。\n\n上述のミニ理論のうち、有機的統合理論は内発的動機づけと外発的動機づけという旧来の二分法を超え、［C］の程度に着目して［D］的動機づけを連続した四つの段階に捉え直し、分類している。すなわち、①［E］、②取り入れ的調整、③同一化的調整、④統合的調整である。［C］が高いほど、課題に粘り強く取り組み、情報を経験や既有知識と結び付けて構造化するような方略を取りやすいとされる。",
