    "question": "アイデンティティの発達に関する記述ア～エのうち、妥当なもののみを挙げているのはどれか。\n\nア. E. H. エリクソンは、自我発達に関して、心理社会的な次元をより重視した独自の理論を展開した。彼の漸成発達図式では、児童期以降になると、心理社会的危機は最優先される時期以前にも何らかの形で存在していると理解される。例えば、青年期では「アイデンティティ 対 アイデンティティ拡散」が優勢であるが、それは、児童期に「時間的展望 対 時間的展望の拡散」として体験されることがある。\nイ. D. エルカインドは、アイデンティティ形成の時期に当たる青年期には、他者からの承認を求める余り、本来関係のない出来事を自己に関連付けるといった関係妄想が生じることがあると述べた。例えば、自分の家柄や血統が優れており、経済力や権力をもっているなど、大げさに空想したり、自己に関する価値を著しく過大に評価したりすることがそれに当たる。\nウ. 現代社会では、アイデンティティは永続的に応用可能なものではなく、社会との関係に応じて断続的にモラトリアムの時期がやってくると考えられている。その場合、アイデンティティは一見達成されても、その後、再びモラトリアムの段階に戻り、新たなアイデンティティ達成に取り組まなければならないという周期が見られる。これを、MAMAサイクルと呼ぶ。\nエ. J. E. マーシャは、半構造化面接を用いて、「危機」と「積極的関与」という次元から、アイデンティティを四つの状態に分類した。例えば、「モラトリアム」に当たる青年は、危機の最中にあり、いくつかの選択肢について迷っているところで、その不確かさを克服しようと懸命に努力している状態といえる。",
