    "question": "幼児期の教育と小学校教育の連携・接続に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA. 教育基本法では、幼児期の教育について、各個人の有する能力を伸ばしつつ社会において自立的に生きる基礎を培い、国家・社会の形成者として必要な基本的資質を養うものであると定めている。また、学校教育法では、幼稚園を「子の教育について第一義的責任を有する」機関として位置付けた上で、幼稚園における教育について、小学校以降の教育との連続性が明確になるよう具体的に目標を規定している。\nB. 文部科学省の「令和3年度幼児教育実態調査」によると、令和3年5月現在、小学校との連携の取組を実施しているとする施設は、幼稚園では約3割にとどまる一方、幼保連携型認定こども園では約5割となっている。公立と私立とを比較すると、幼稚園及び幼保連携型認定こども園のいずれにおいても、公立よりも私立の方が小学校との連携の取組を実施しているとする施設の割合が高い状況にある。\nC. 幼稚園教育と小学校教育の円滑な接続を図るため、平成29年に改訂された幼稚園教育要領では、「小学校入学後に育ってほしい姿」として、健康な心と体、自立心などが明記されている。同年に改訂された小学校学習指導要領では、特に入学当初において、幼稚園教育要領等に基づく幼児期の教育を確実に各教科等における学習に接続するため、教科ごとに幼児期の教育と関連付けながらそれぞれ独自の指導計画を作成し実施するとしている。\nD. 文部科学省は、幼児教育と小学校教育は、教育課程の構成原理など様々な違いから円滑な接続を図ることは容易でないとして、義務教育開始前後の5歳児から小学校1年生の2年間の「架け橋期」に焦点を当てその時期にふさわしい学びの実現を図る「幼保小の架け橋プログラム」を推進するとしている。ここでは、0歳から18歳までの学びの連続性に配慮しつつ、「架け橋期」の教育の充実を図り、生涯にわたる学びや生活の基盤をつくることが重要とされている。",
