    "difficulty": 3,
    "question": "教育振興基本計画は、我が国の教育振興に関する施策の総合的・計画的な推進を図るため、教育基本法に基づき政府として策定するものであり、現在は第4期計画の期間中である。\n次は、第1期計画、第2期計画、第3期計画、第4期計画のそれぞれに関する記述であるが、A～Dを古いものから順に並べたものとして最も妥当なのはどれか。\n\nA. 「教育立国」を宣言し、我が国の未来を切り拓く教育の振興に社会全体で取り組んでいくことを目指すこととした。社会全体で教育の向上に取り組むこととし、地域が学校を支援する仕組みづくり（学校支援地域本部）や放課後等の子どもたちの学習・体験活動等の場づくり（「放課後子どもプラン」等）の実施を促すこととした。\nB. 教育を通じて生涯にわたる一人一人の「可能性」と「チャンス」を最大化することを今後の教育政策の中心に据えて取り組むこととし、基本的な方針の一つとして、教育政策推進のための基盤を整備することが示された。ICT利活用のための基盤の整備については、学習者用コンピュータを3クラスに1クラス分程度整備すること、普通教室に無線LANを100％整備することを測定指標として進捗状況を把握しながら実効性のある教育政策を進めることとした。\nC. 持続可能な社会の創り手の育成、日本社会に根差したウェルビーイングの向上が掲げられ、グローバル化する社会の持続的な発展に向けて学び続ける人材の育成、誰一人取り残されず、全ての人の可能性を引き出す共生社会の実現に向けた教育の推進、地域や家庭で共に学び支え合う社会の実現に向けた教育の推進、教育デジタルトランスフォーメーション（DX）の推進、計画の実効性確保のための基盤整備・対話が基本的な方針とされた。\nD. 東日本大震災により我が国を取り巻く危機的状況が顕在化・加速化したことなどから、一人一人の「自立」した個人が多様な個性・能力を生かし、他者と「協働」しながら新たな価値を「創造」していくことができる「生涯学習社会」の構築を目指すこととした。そして、社会を生き抜く力の養成、未来への飛躍を実現する人材の育成、学びのセーフティネットの構築、絆づくりと活力あるコミュニティの形成の四つを教育行政の基本的方向性として設定した。",
