    "question": "我が国における教育の情報化に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA. 文部科学省の「令和4年度学校における教育の情報化の実態等に関する調査結果」によると、2023年3月現在、小・中学校における教育用コンピュータ1台当たりの児童生徒数は平均1.8人を超えており、平均値でみると「1人1台端末」が達成されていない状況にある。また、教員の校務用コンピュータの整備率は50％を下回っており、半数以上の教員が校務に私物端末を用いざるを得ない状況にある。\nB. 文部科学省は、新型コロナウイルス感染症の感染拡大による一斉休校を契機として、学びの自律化や個別最適化などを掲げる「未来の教室」事業を開始した。同事業の対象となった学校では、義務教育段階においてもEdTechを活用してオンラインによる授業のみで課程の修了とみなす学校教育が実施されており、不登校を含む多様な児童生徒の学びの保障も行っている。\nC. 2022年に実施されたPISA調査によると、学校の各教科の授業におけるICTの利用頻度はOECD加盟国の平均を上回り、特に、生徒自身が情報を集め、集めた情報を記録・分析・報告するなどの場面でICTを使う頻度を示す「ICTを用いた探究型の教育の頻度」の指標は、OECD加盟国で第1位であった。\nD. 文部科学省は、質の高い学習の実現に資するとして、遠隔教育の推進を掲げており、2019年には中学校等＊において、文部科学大臣が定める基準を満たしていると認められる場合、配信側の教員が当該教科の教員免許状を有していれば、受信側の教員が当該教科の教員免許状を有していない状況でも遠隔で授業を行うことを可能とする「遠隔教育特例校」を制度化した。\n\n＊ 中学校、義務教育学校後期課程、中等教育学校前期課程及び特別支援学校中学部",
