    "difficulty": 3,
    "question": "次は、正統的周辺参加（legitimate peripheral participation）に関する記述であるが、A～Dに当てはまるものの組合せとして最も妥当なのはどれか。\n\nFirst, as we began to focus on legitimate peripheral participation, we wanted above all to take a fresh look at learning. Issues of learning and schooling seemed to have become too deeply interrelated in our culture in general, both for purposes of our own exploration and the exposition of our ideas. More importantly, the organization of schooling as an educational form is predicated on claims that ［A］ can be decontextualized, and yet schools themselves as social institutions and as places of learning constitute very ［B］ contexts. Thus, analysis of school learning as situated requires a multilayered view of how knowing and learning are part of social practice — a major project in its own right.\n\n《中略》\n\nWe should emphasize, therefore, that legitimate peripheral participation is not itself an educational form, much less a pedagogical strategy or a teaching technique. It is ［C］＊ viewpoint on learning, a way of understanding learning. We hope to make clear as we proceed that learning through legitimate peripheral participation takes place no matter which educational form provides a context for learning, or whether there is any ［D］ educational form at all. Indeed, this viewpoint makes a fundamental distinction between learning and ［D］ instruction. Such decoupling does not deny that learning can take place where there is teaching, but does not take ［D］ instruction to be in itself the source or cause of learning, and thus does not blunt the claim that what gets learned is problematic with respect to what is taught. Undoubtedly, ［C］＊ perspective of legitimate peripheral participation could — we hope that it will — inform educational endeavors by shedding a new light on learning processes, and by drawing attention to key aspects of learning experience that may be overlooked.\n\n＊ この空欄に入る単語には、それぞれ適当な冠詞（a／an／the）が付く。",
