      "イ": "1980年代半ばに、社会保障審議会答申で地域包括ケアシステムの確立の必要性が提起されたが、包括する事業の範囲やその担い手等の整理に年月を要した結果、地域包括ケアシステムの名称が法律上初めて使用され定義付けられたのは、2020年公布の改正介護保険法であった。地域包括ケアシステムが法的に位置付けられたことを受け、日中・夜間を通じて介護・看護等のサービスを一体的に提供する24時間対応の「定期巡回・随時対応サービス」が新設された。",
