    "difficulty": 3,
    "question": "説得や行動変容に関する記述ア〜エのうち、妥当なもののみを挙げているのはどれか。\n\nア．R.E. ペティと J.T. カシオッポが提唱した精緻化見込みモデルによると、態度変容は精緻化の結果として「中心的ルート」により生じるものと、精緻化を伴わず「周辺的ルート」により生じるものがあるという。このときの精緻化とは、内容に対して受動的な情報処理が行われることを指し、中心的ルートによって生じた態度変容の方が周辺的ルートによって生じた態度変容よりも維持されにくい。\n\nイ．W.J. マクガイアによる接種理論とは、受け手に、説得への抵抗をつける方法を扱った理論である。この理論によると、自明の理に対する弱い反論を論破する経験をさせると、その後に更に反論にさらされても強い抵抗を示すことができるようになる。予防接種によって病原体への免疫を高めておくことに似ていることから、接種理論と呼ばれている。\n\nウ．S. チェイキンらによるヒューリスティック・システマティック・モデルは、人間が必要に迫られた場合に、複雑かつ活発な情報の認知的処理を行うという「認知的節約家」の概念に基づいている。このモデルでは、情報を十分に吟味して熟考する処理であるシステマティック処理と、迅速だが安直な情報処理であるヒューリスティック処理の二つが仮定されている。\n\nエ．I. エイゼンによる計画的行動理論では、我々の意図的な行動に直接的な影響を与えている要因は行動意図である。行動意図は、行動抑制システム、行動接近システム、コントロール感の三つの要因によって規定される。これら三つの要因は、行動に直接的な影響を及ぼさず、行動意図を介して行動に影響を及ぼすと仮定されている。",
    "choices": {
      "ア": "ア、イ",
      "イ": "ア、エ",
      "ウ": "イ、ウ",
      "エ": "イ、エ",
      "オ": "ウ、エ"
    },
