    "difficulty": 3,
    "question": "流言と集合行動に関する記述ア〜エのうち、妥当なもののみを挙げているのはどれか。\n\nア．G. W. オルポートらは、「流言の流布量（R）は当事者にとっての問題の重要性（i）と内容のもっともらしさ・適切さ（a）との和によって決定する（R〜i＋a）」という公式を提起した。その公式に基づくと、当事者にとって重要な問題であり、もっともらしく適切な内容であるほど、流言は増えるとされている。\n\nイ．災害発生時のような緊急事態では、人々の不安が高まるとともに、情報が遮断されて状況の曖昧さも高まる。廣井脩は、こうした状況下で生じる流言を「浸透流言」と呼び、平常時の「噴出流言」と区別した。廣井によれば、浸透流言には災害発生時の緊急対応の指示等が含まれることが多く、情報の信頼性が重視されるという観点から、日常的なコミュニケーション・ネットワークの中で特に浸透し、見知らぬ他者に伝播することは極めてまれであるとされている。\n\nウ．G. ル・ボンは、群衆には、匿名性が高まって責任感が欠如する、感情的になり動揺・興奮しやすくなるといった特性があり、そうした特性ゆえに互いの感情や思考が容易に感染し、結果的に等質化していくと論じた。また、G. タルドは、人々の行動は模倣により成り立つとし、新聞等を媒介として、直接的に接触せずとも意見や価値観が伝染するとした。\n\nエ．R. H. ターナーと L. M. キリアンの創発規範説に基づけば、非日常的な状況においては、その危機的状況の中で適応していくための非日常的な規範が生じ、人々はその規範に従って行動するようになるとされている。彼らは、集合行動を、人々が感情感染により社会規範を逸脱した行動を取った結果としてではなく、異常事態の中で人々の間に模索され創出された規範、つまり創発規範にのっとって行動した結果であると考えた。",
